// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: the candidate newOwner and the caller who must be the current owner
    function testFuzz_property(address newOwner, address caller) public {
        // keep addresses practical (non-zero) but wide
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));

        // Ensure contract's owner is the caller by deploying c in setUp (owner == address(this))
        // So we need to impersonate the initial owner to transfer ownership to `caller` first.
        // The initial owner is the test contract (address(this)), so perform setOwner to make `caller` the owner.
        // First, as the initial owner (this), set owner to caller
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the above failed for some reason, abort this input (shouldn't for correct contract)
        vm.assume(ok);

        // Now caller should be the owner. Impersonate `caller` and call setOwner(newOwner).
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assertion: for the correct contract, after an owner-invoked setOwner(newOwner), owner() == newOwner.
        // The mutant that assigns tx.origin instead will set owner to tx.origin (which equals the original EOA
        // that initiated the transaction) and thus for many (caller, newOwner) pairs will differ.
        assertTrue(ok && c.owner() == newOwner);
    }
}

