import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: newOwner is the candidate owner address provided to setOwner
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: disallow zero address as an initial owner replacement is allowed but
        // we still want to allow zero here to let fuzzer explore it. No vm.assume needed.

        // Ensure the caller is the current owner (deployer). The contract's constructor set owner = msg.sender
        // which is this test contract address by default. So call as this contract.

        // Call setOwner with fuzzed newOwner
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: when the call succeeds, C.owner() equals the supplied newOwner.
        // This holds for the reference implementation for all inputs; the mutant that sets owner = address(0)
        // will make this assertion fail for any newOwner != address(0).
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, still assert that owner was unchanged (defensive), but
            // to keep the single required assertion structure we skip asserting on revert path.
            // We still require at least one assertion reading c when ok is true; the fuzzer will
            // find inputs where ok is true and the mutant fails.
            assertTrue(true);
        }
    }
}

