import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: an address newOwner and an address caller which may be either EOA or a contract
    // We will deploy a helper ContractCaller at callerAddr when the caller is a contract (determined by non-zero code flag)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep inputs wide but avoid zero-address newOwner to make semantics clear
        vm.assume(newOwner != address(0));

        // Ensure caller is not the initial owner to cover interesting cases (initial owner is address(this) in setUp? actually new C() sets owner to msg.sender which is address(this) of test contract)
        // The test harness (forge) runs setUp from this test contract, so c.owner() == address(this). We fuzz caller to be different or same.

        // We'll simulate a contract caller when the caller address is a contract by deploying a helper and using its address.
        // If the fuzzed caller is an EOA (no code), we will use that EOA via vm.prank. If it's equal to address(0), we've excluded it above.

        // Deploy a helper contract that will call c.setOwner(newOwner) from its context. This simulates an indirect call where tx.origin is the test EOA
        ContractCaller helper = new ContractCaller(c);

        // 1) Case A: direct call by the owner (address(this)) should always allow changing owner in reference.
        //    We perform it first to establish baseline: owner becomes directOwnerNew.
        address directOwnerNew = newOwner;
        // call as current owner (this test contract) -> should succeed on reference
        vm.prank(address(this));
        bool okDirect;
        try c.setOwner(directOwnerNew) { okDirect = true; } catch { okDirect = false; }
        // After this call reference C sets owner to directOwnerNew. Mutant also: since msg.sender == owner holds for reference call path, both versions would change owner here.

        // 2) Now prepare an invocation where the transaction origin is the original owner but the immediate caller is a contract.
        // We need to run the call such that tx.origin == address(this) but msg.sender == helper.
        // Forge cannot set tx.origin arbitrarily; tx.origin will be the externally-owned account running the test (the test runner). To simulate tx.origin == address(this), we make the test contract be the tx.origin by executing the external call from this contract. In Foundry tests, calls made via this test contract have tx.origin == tx.origin_of_fork which is not controllable; however, the distinguishing scenario is that the call comes from a contract (helper) while the owner's EOA initiated it — we can emulate this by having this test contract call helper which in turn calls c.
        // Use the helper to call c.setOwner(newOwner) but perform the call by this contract so tx.origin == the external runner; for our purposes, the mutant checks tx.origin == owner, where owner currently equals directOwnerNew (set above). We want tx.origin to equal the owner to trigger mutant allowing the change but msg.sender != owner so reference disallows.

        // To make tx.origin equal to owner, we need owner to be an EOA that equals tx.origin. In Foundry tests, tx.origin is the address of the externally controlled account running the test (the default caller). That is not equal to address(this). Therefore we should not have set owner to directOwnerNew unless directOwnerNew equals tx.origin. To keep the test general, we instead revert to initial owner which is address(this) from setUp. We will reset owner back to address(this) (the test contract) by calling setOwner from address(this) again if needed.
